// liefert einen Eintrag mit ok/err; Spieler warten auf ok, statt ein
// halb geladenes Bild sichtbar zu wechseln (kein Flash, kein Leerraum).
const _bildCache = new Map();
function bildLaden(src){
  let eintrag = _bildCache.get(src);
  if(!eintrag){
    const img = new Image();
    eintrag = { ok:false, err:false };
    img.onload = () => { eintrag.ok = true; };
    img.onerror = () => { eintrag.err = true; };
    img.src = src;
    _bildCache.set(src, eintrag);
  }
  return eintrag;
}

